// Telegram-Nachricht aus den fälligen Stellen bauen (Klartext, ohne Markdown).
const items = $input.all().filter(it => it.json && (it.json.fields || it.json.id));
const today = $now.toFormat('dd.MM.yyyy');
const rows = [];
for (const it of items) {
  const f = it.json.fields || it.json;
  const title = f['Stellentitel'] || '(ohne Titel)';
  const status = f['Status'] || '?';
  const due = f['Nachfassen am'] ? $now.constructor.fromISO(f['Nachfassen am']).toFormat('dd.MM.yyyy') : '?';
  const applied = f['Beworben am'] ? ', beworben am ' + $now.constructor.fromISO(f['Beworben am']).toFormat('dd.MM.yyyy') : '';
  const link = f['Link zur Stelle'] ? '\n   ' + f['Link zur Stelle'] : '';
  rows.push(`• ${title}\n   Status: ${status}${applied}, nachfassen seit: ${due}${link}`);
}
if (!rows.length) return [{ json: { count: 0 } }];   // nichts fällig: keine Nachricht (v1.2: Lauf gilt trotzdem als erfolgreich)
const text = [`📌 Nachfassen heute (${today}): ${rows.length} Stelle(n)`, '', ...rows, '', 'Nach dem Nachfassen in Airtable das Datum leeren oder neu setzen.'].join('\n');
return [{ json: { text, count: rows.length } }];
